86	    /// Add the maximum stack used to a register, recording an obligation to update the
87	    /// add-with-immediate instruction emitted to use the real stack max when the masm is being
88	    /// finalized.
89	    fn add_stack_max(&mut self, reg: WritableReg, tmp: WritableReg) {
90	        assert!(self.stack_max_use_add.is_none());
91	        let patch = PatchableAddToReg::new(reg, tmp, self.asm.buffer_mut());
92	        self.stack_max_use_add.replace(patch);
93	    }
