    /// Add with three registers, setting flags, using the shifted-register
    /// encoding.
    ///
    /// Unlike [`Self::adds_rrr`], which uses the extended-register encoding,
    /// this emits the plain `adds rd, rn, rm` form used to set the carry flag
    /// for the low word of a 128-bit addition.
    pub fn adds_rrr_shift(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::AddS, rm, rn, rd, size);
    }

    /// Add with carry with three registers.
    ///
    /// Used for the high word of a 128-bit addition, consuming the carry flag
    /// produced by a preceding [`Self::adds_rrr_shift`].
    pub fn adc_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::Adc, rm, rn, rd, size);
    }

    /// Subtract with three registers, setting flags, using the
    /// shifted-register encoding.
    ///
    /// This emits the plain `subs rd, rn, rm` form used to set the borrow flag
    /// for the low word of a 128-bit subtraction.
    pub fn subs_rrr_shift(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::SubS, rm, rn, rd, size);
    }

    /// Subtract with carry (borrow) with three registers.
    ///
    /// Used for the high word of a 128-bit subtraction, consuming the borrow
    /// flag produced by a preceding [`Self::subs_rrr_shift`].
    pub fn sbc_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::Sbc, rm, rn, rd, size);
    }

