    pub fn smulh_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::SMulH, rm, rn, rd, size);
    }

    /// Unsigned multiply high with three registers, producing the high 64 bits
